record.field:
# ─── 1. Create project.project from won lead ─── if record.stage_id and record.stage_id.is_won: service_type = record.x_hexa_service or 'general' partner = record.partner_id if not partner: raise UserError('Lead must have a linked contact before conversion.')
project_vals = { 'name': record.name or 'New Project', 'partner_id': partner.id, 'x_hexa_type': service_type, 'date_start': fields.Date.today(), 'user_id': record.user_id.id if record.user_id else env.uid, 'description': record.description or '', }
# Also copy x_hexa_service and other custom fields if they exist if hasattr(record, 'x_hexa_source'): project_vals['x_hexa_source'] = record.x_hexa_source if hasattr(record, 'x_hexa_budget'): project_vals['x_hexa_budget'] = record.x_hexa_budget
project = env['project.project'].create(project_vals)
# ─── 2. Create default milestones based on project type ─── milestone_templates = { 'architectural_design': [ ('Discovery & Requirements', 1), ('Concept Design', 2), ('Schematic Design', 3), ('Design Development', 4), ('Final Delivery', 5), ], 'interior_design': [ ('Space Planning', 1), ('Mood Board & Concept', 2), ('3D Visualization', 3), ('Material Selection', 4), ('Final Presentation', 5), ], '3d_visualization': [ ('Reference Collection', 1), ('Blockout & Composition', 2), ('Lighting & Materials', 3), ('Final Renders', 4), ('Post-Production & Delivery', 5), ], 'branding': [ ('Brand Discovery', 1), ('Logo & Identity Concepts', 2), ('Design System & Guidelines', 3), ('Collateral & Assets', 4), ('Brand Launch Kit', 5), ], 'general': [ ('Project Kickoff', 1), ('Phase 1 — Research', 2), ('Phase 2 — Execution', 3), ('Phase 3 — Review', 4), ('Final Delivery & Handover', 5), ], }
milestones = milestone_templates.get(service_type, milestone_templates['general']) milestone_ids = [] for name, order in milestones: milestone = env['project.milestone'].create({ 'name': name, 'project_id': project.id, 'x_hexa_order': order, 'x_hexa_client_viewable': True, }) milestone_ids.append(milestone.id)
# ─── 3. Send welcome email to client ─── welcome_template = env.ref('hexa_studio.hexa_welcome_email', raise_if_not_found=False) if welcome_template and partner.email: welcome_template.send_mail(project.id, force_send=True)
# ─── 4. Create mail.activity for PM to schedule kickoff meeting ─── activity_type = env['mail.activity.type'].search([('name', 'ilike', 'meeting')], limit=1) if activity_type: env['mail.activity'].create({ 'res_model_id': env.ref('project.model_project_project').id, 'res_id': project.id, 'activity_type_id': activity_type.id, 'summary': 'Schedule Kickoff Meeting', 'note': ( f'New project "{record.name}" has been created from a won lead.\n' f'Client: {partner.name}\n' f'Email: {partner.email or "N/A"}\n' f'Service: {service_type}\n\n' f'Please schedule the kickoff meeting within 48 hours.' ), 'user_id': record.user_id.id if record.user_id else env.uid, 'date_deadline': fields.Date.today() + datetime.timedelta(days=2), })
# Link the lead to the project for traceability record.write({'x_hexa_project_id': project.id})
action = { 'type': 'ir.actions.client', 'tag': 'display_notification', 'params': { 'title': 'Project Created', 'message': f'Project "{project.name}" created with {len(milestones)} milestones.', 'type': 'success', 'sticky': False, }, }
